import json
from codesign.challenge.hardware import Hardware
from codesign.challenge.isa import iter_parse
from codesign.challenge.pipeline import estimate_pipeline
from codesign.challenge.hbm_race import validate_hbm_races

with open('hardware.json') as f:
    hw = Hardware(**json.load(f))

# Test BARRIER between wg0 and wg1
prog = '''WG.BEGIN {\"wg\": \"wg0\", \"sm\": 0, \"shared_bytes\": 0}
WG.BEGIN {\"wg\": \"wg1\", \"sm\": 1, \"shared_bytes\": 0}
VEC {\"kind\": \"add\", \"src\": [{\"imm\": 0.0}, {\"imm\": 0.0}], \"dst\": {\"space\": \"RF\", \"offset\": 0, \"count\": 16, \"wg\": \"wg0\", \"lane\": 0}, \"event\": \"e0\"}
VEC {\"kind\": \"add\", \"src\": [{\"imm\": 0.0}, {\"imm\": 0.0}], \"dst\": {\"space\": \"RF\", \"offset\": 0, \"count\": 16, \"wg\": \"wg1\", \"lane\": 0}, \"event\": \"e1\"}
BARRIER {\"wgs\": [\"wg0\", \"wg1\"], \"events\": [\"e0\", \"e1\"]}
WG.END {\"wg\": \"wg0\"}
WG.END {\"wg\": \"wg1\"}'''

validate_hbm_races(prog)
res = estimate_pipeline(hw, iter_parse(prog), 1000)
print('Barrier test passed, cycles:', res.cycles)
"

